INSERT INTO nhl_coaching_insights (game_id,insight_key,available_at_game_seconds,expires_at_game_seconds,priority,category,severity,title,summary,related_widget_keys,payload) VALUES
  ('2025030414','opening-pressure',42,NULL,96,'game-state','high','Carolina established the first-shot advantage','Aho generated the first shot on goal 42 seconds into the game. Keep the high forward press after neutral-zone wins.','["shots-on-goal","game-flow","video-review"]'::jsonb,'{"player":20,"eventSecond":42}'::jsonb),
  ('2025030414','staal-faceoff-edge',768,NULL,100,'faceoffs','high','Staal is controlling the decisive draws','Jordan Staal finished 12–4 on faceoffs and converted the first-period power play. Prioritize him for defensive-zone and late-game draws.','["head-to-head-faceoffs","faceoff-win-rate","offensive-zone-faceoff","opening-faceoff"]'::jsonb,'{"wins":12,"losses":4,"faceoffPct":75}'::jsonb),
  ('2025030414','ehlers-impact',2392,NULL,91,'player-impact','medium','Ehlers is driving the second scoring layer','Nikolaj Ehlers finished with three points and the empty-net goal while adding value on faceoffs.','["player-impact","game-points","shots-on-goal"]'::jsonb,'{"goals":1,"assists":2,"points":3}'::jsonb),
  ('2025030414','protect-middle',2228,2580,88,'defensive','high','Vegas has tied the game through the middle lane','After Howden''s equalizer, tighten the slot and force Vegas to the outside before the next offensive push.','["shooting-by-sector","lineup-analyzer","recent-events"]'::jsonb,'{"score":"3-3","eventSecond":2228}'::jsonb),
  ('2025030414','late-lead',2792,NULL,98,'game-state','high','Staal restored the lead','With Carolina ahead 4–3, use the Staal line for defensive-zone starts and keep Slavin available for the next matchup.','["player-toi","lineup-analyzer","faceoff-win-rate"]'::jsonb,'{"score":"4-3","eventSecond":2792}'::jsonb)
